class Solution:
    def findMaximums(self, nums: List[int]) -> List[int]:
        n = len(nums)
        ans = []
        win = nums[:]
        while win:
            ans.append(max(win))
            win = [min(a, b) for a, b in zip(win, nums[len(ans):])]
        return ans

