class Solution {
    public int[] findMaximums(int[] nums) {
        int n = nums.length;
        int[] ans = new int[n];
        int[] win = nums.clone();
        for (int w = 0; w < n; w++) {
            int mx = Integer.MIN_VALUE;
            for (int x : win) mx = Math.max(mx, x);
            ans[w] = mx;
            int[] nxt = new int[Math.max(win.length - 1, 0)];
            for (int i = 0; i < nxt.length; i++) {
                nxt[i] = Math.min(win[i], nums[i + w + 1]);
            }
            win = nxt;
        }
        return ans;
    }
}

