var findMaximums = function(nums) {
    const n = nums.length;
    const ans = [];
    let win = [...nums];
    while (win.length) {
        let mx = win[0];
        for (const v of win) if (v > mx) mx = v;
        ans.push(mx);
        const size = ans.length;
        win = win.slice(0, win.length - 1).map((v, i) => Math.min(v, nums[i + size]));
    }
    return ans;
};

