class Solution:
    def findMaximums(self, nums: List[int]) -> List[int]:
        n = len(nums)
        left = [-1] * n
        right = [n] * n
        st = []
        for i in range(n):
            while st and nums[st[-1]] >= nums[i]:
                st.pop()
            left[i] = st[-1] if st else -1
            st.append(i)
        st = []
        for i in range(n - 1, -1, -1):
            while st and nums[st[-1]] > nums[i]:
                st.pop()
            right[i] = st[-1] if st else n
            st.append(i)
        best = [0] * (n + 2)
        for i in range(n):
            span = right[i] - left[i] - 1
            best[span] = max(best[span], nums[i])
        for w in range(n - 1, 0, -1):
            best[w] = max(best[w], best[w + 1])
        return [best[w] for w in range(1, n + 1)]

