class Solution {
public:
    vector<int> findMaximums(vector<int>& nums) {
        int n = nums.size();
        vector<int> left(n, -1), right(n, n);
        vector<int> st;
        for (int i = 0; i < n; i++) {
            while (!st.empty() && nums[st.back()] >= nums[i]) st.pop_back();
            left[i] = st.empty() ? -1 : st.back();
            st.push_back(i);
        }
        st.clear();
        for (int i = n - 1; i >= 0; i--) {
            while (!st.empty() && nums[st.back()] > nums[i]) st.pop_back();
            right[i] = st.empty() ? n : st.back();
            st.push_back(i);
        }
        vector<int> best(n + 2, 0);
        for (int i = 0; i < n; i++)
            best[right[i] - left[i] - 1] = max(best[right[i] - left[i] - 1], nums[i]);
        for (int w = n - 1; w >= 1; w--)
            best[w] = max(best[w], best[w + 1]);
        return vector<int>(best.begin() + 1, best.begin() + n + 1);
    }
};

