var findMaximums = function(nums) {
    const n = nums.length;
    const left = new Array(n).fill(-1);
    const right = new Array(n).fill(n);
    let st = [];
    for (let i = 0; i < n; i++) {
        while (st.length && nums[st[st.length - 1]] >= nums[i]) st.pop();
        left[i] = st.length ? st[st.length - 1] : -1;
        st.push(i);
    }
    st = [];
    for (let i = n - 1; i >= 0; i--) {
        while (st.length && nums[st[st.length - 1]] > nums[i]) st.pop();
        right[i] = st.length ? st[st.length - 1] : n;
        st.push(i);
    }
    const best = new Array(n + 2).fill(0);
    for (let i = 0; i < n; i++) {
        const span = right[i] - left[i] - 1;
        best[span] = Math.max(best[span], nums[i]);
    }
    for (let w = n - 1; w >= 1; w--) best[w] = Math.max(best[w], best[w + 1]);
    const ans = [];
    for (let w = 1; w <= n; w++) ans.push(best[w]);
    return ans;
};
